```cpp
const auto drawPipMaker = [&]() {
    double previousPos = 0;
    return [previousPos, &](const auto row, const auto rightAlign, const auto& brush) mutable {
         // This assumes that "row" is sorted (either ascending or descending).
         if (std::abs(newPos - previousPos) < onePixel)
         {
             return;
         }
         // ...
    };
};
// ...
auto drawPip = drawPipMaker();
// ...
auto drawPip = drawPipMaker();
// ...
```

